window.docContents[124].resolve({"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Using-Evidence-in-Proofs--Induction-on-Evidence":{"contents":"If this story feels familiar, it is no coincidence: We\nencountered similar problems in the Induction chapter,\nwhen trying to use case analysis to prove results that required\ninduction.  And once again the solution is... induction!\n\n\n\nLet's try proving that lemma again:\n\ntheorem even_even (n : Nat) (h : Even n) : Nat.Even n := by\n  induction h with\n  | zero => exists 0 -- (`0 = double 0` is closed by `exists`'s final `rfl`)\n  | succ_succ h' ih =>\n    let ⟨k, hk⟩ := ih\n    exists k + 1; rw [Nat.double_succ, hk]\n\n\n\n\n\n\n","context":"Logical Foundations\u0009IndProp: Inductively Defined Propositions\u0009Using Evidence in Proofs","header":"9.2.2. Induction on Evidence","id":"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Using-Evidence-in-Proofs--Induction-on-Evidence"}});